import sys,re
def load(path):
    data=open(path,'rb').read().decode('latin-1').split('\n')
    hdr=data[0].split()
    sig=hdr[0]
    hard=sig[5] if len(sig)>5 else ' '
    h=int(hdr[1]); base=int(hdr[2]); maxlen=int(hdr[3]); old=int(hdr[4]); cmt=int(hdr[5])
    pd=int(hdr[6]) if len(hdr)>6 else 0
    full=int(hdr[7]) if len(hdr)>7 else None
    ctc=int(hdr[8]) if len(hdr)>8 else None
    i=1+cmt
    chars={}
    codes=list(range(32,127))+[196,214,220,228,246,252,223]
    def readchar(i):
        rows=[]
        for r in range(h):
            line=data[i].rstrip('\r'); i+=1
            if len(line)==0: rows.append(''); continue
            k=len(line)-1
            e=line[k]
            while k>=0 and line[k]==e: k-=1
            rows.append(line[:k+1])
        return rows,i
    for c in codes:
        rows,i=readchar(i)
        chars[c]=rows
    while i<len(data):
        line=data[i]
        if line.strip()=='' : 
            i+=1; continue
        tok=line.split()[0]
        try:
            code=int(tok,0) if not tok.startswith('-') else -int(tok[1:],0)
        except: break
        i+=1
        rows,i=readchar(i)
        chars[code]=rows
    return dict(sig=sig,hard=hard,h=h,base=base,maxlen=maxlen,old=old,cmt=cmt,pd=pd,full=full,ctc=ctc,chars=chars)
if __name__=='__main__':
    f=load(sys.argv[1])
    print(f['sig'],repr(f['hard']),f['h'],f['base'],f['maxlen'],f['old'],f['cmt'],f['pd'],f['full'],f['ctc'],'nchars=',len(f['chars']))
    if len(sys.argv)>2:
        if sys.argv[2]=='find':
            pat=sys.stdin.read().rstrip('\n').split('\n')
            for c,rows in f['chars'].items():
                if [r.rstrip() for r in rows][:len(pat)]==[p.rstrip() for p in pat]: print("MATCH",c,hex(c) if c>0 else '')
        else:
            c=int(sys.argv[2],0)
            for r in f['chars'][c]: print('['+r+']')
