import subprocess
req=list(range(32,127))+[196,214,220,228,246,252,223]
def mkfont(name, nums, sig="flf2a$"):
    out=[sig+" "+" ".join(str(x) for x in nums),"c"]
    for c in req:
        ch=chr(c) if 32<=c<127 else ' '
        out.append(' '+ch+' @')
    open(name+'.flf','w').write('\n'.join(out)+'\n')
TESTS=['aa','ab','_|','|/','()','/\\','$$']
def sig(font,flags=[]):
    inp='\n'.join(TESTS)+'\n'
    p=subprocess.run(['/workspace/executable','-d','/tmp/rev','-f',font,'-w','4000']+flags,
        input=inp.encode('latin-1'),capture_output=True)
    return '|'.join(p.stdout.decode('latin-1').split('\n')[:len(TESTS)])+ ('  ERR:'+p.stderr.decode()[:60] if p.stderr else '')
